source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 -c "
import wandb
api = wandb.Api()
run = api.run('xiaoyucorynne-/cost-verify-agent-rl/4yu6qz1m')
# Get ALL history rows - each row separately
all_rows = list(run.scan_history(page_size=500))
print(f'Total rows: {len(all_rows)}')
for i, row in enumerate(all_rows):
    # Filter out None values and internal keys
    filtered = {}
    for k, v in row.items():
        if v is not None and k not in ('_timestamp', '_runtime'):
            if isinstance(v, float):
                filtered[k] = round(v, 4)
            elif isinstance(v, str) and len(v) > 50:
                continue  # skip long strings
            else:
                filtered[k] = v
    step = filtered.pop('_step', '?')
    # Only show key metrics
    important = {k: v for k, v in filtered.items() if any(x in k for x in ['success', 'pass@', 'action_is_valid', 'entropy', 'kl_loss', 'pg_loss', 'ppo_kl', 'score/mean', 'rewards/mean', 'num_actions', 'grad_norm'])}
    if important:
        print(f'row={i} step={step} | {important}')
" 2>&1
